      "«جنگ ستارگان: امپراطوری ضربه می زند»، فیلمی در ژانر علمی-تخیلی، اکشن و ماجراجویی، به کارگردانی «اروین کرشنر» و محصول سال 1980 سینمای آمریکاست. این فیلم پس از اکران موفق و استقبال چشمگیر مخاطبین و منتقدین، حضوری درخشان در جشنواره های داخلی و بین المللی معتبری چون آکادمی اسکار، بفتا و گلدن گلوب داشت و توانست نامزد دریافت 45 جایزه در بخش های مختلف شود که در این بین، 25 جایزه همچون اسکار «بهترین جلوه های تصویری» را با خود به خانه برده است. در این فیلم که دومین فیلم از سری فیلم های «جنگ ستارگان» بوده و از نظر سیر زمان قسمت پنجم است، «مارک هامیل»، «کری فیشر» و «هریسون فورد» خوش درخشیده اند. از دیگر افتخارات این فیلم خارق العاده، کسب رتبه 15 در بین 250 فیلم برتر تاریخ، از نگاه سایت معتبر آی.ام.دی.بی است. داستان این فیلم فوق العاده جذاب و با شکوه، از آنجایی آغاز می شود که نیروهای امپراطور و شورشیان، در سیاره یخ زده هاث، به طرز بی رحمانه ای درگیر می شوند و پس از آن لوک اسکای واکر به تعلیم فنون جدای با یودا می پردازد؛ در حالیکه دوستانش در سر تاسر کهکشان تحت تعقیب هستند...",
