      "«جنگ ستارگان: امید تازه»، فیلمی در ژانر علمی-تخیلی، اکشن و ماجراجویی، به کارگردانی «جورج لوکاس»، محصول سال 1977 سینمای آمریکا و از تولیدات کمپانی فاکس قرن 20 است. این فیلم پس از اکران عمومی و فروشی فوق العاده، حضوری درخشان در جشنواره های داخلی و بین المللی معتبری چون آکادمی اسکار، بفتا و گلدن گلوب داشت و موفق شد نامزد دریافت 92 جایزه شود که در این بین، 63 جایزه همچون 6 اسکار «بهترین کارگردانی هنری» و «بهترین موسیقی اورجینال» و... را از آن خود کرده است. در این فیلم که اولین فیلم از سری فیلم های جنگ ستارگان و از نظر سیر زمان، قسمت چهارم است، ستارگانی چون «مارک هامیل»، «کری فیشر» و «هریسون فورد» به هنرنمایی پرداخته اند. از دیگر افتخارات این شاهکار، کسب رتبه 25 در بین 250 فیلم برتر تاریخ سینما، از دیدگاه سایت معتبر آی.ام.دی.بی است. داستان این فیلم پیشگام که ترکیب مناسبی از ماجراجویی، شخصیت های دوست داشتنی و داستانی حماسی است، درباره دو ربات است که به دنبال اوبی وان کنوبی می گردند و در این راه، لوک اسکای واکر جوان برای کمک به آن ها، سیاره محل سکونت خود را به همراه اوبی وان و هان سولو ترک می کند، تا برای نجات پرنسس لیا و کهکشان، به سایر شورشیان بپیوندد...",
