      "«3 احمق»، فیلمی در ژانر کمدی-خانوادگی و درام، به کارگردانی «راجکومار هیرانی» و محصول سال 2009 سینمای هند است. این فیلم، پس از اکران موفق و استقبال و تحسین چشمگیر مخاطبین و منتقدین، حضوری درخشان در فستیوالهای معتبر داخلی و بین المللی داشت و توانست افتخارات فراوانی کسب کند؛ موفق شد نامزد 87 جایزه در بخش های مختلف شود که در این میان، 64 جایزه همچون «بهترین فیلم»، «بهترین کارگردانی» و «بهترین بازیگر نقش اول مرد» را از آن خود کرده است. این فیلم که محبوب ترین کمدی بالیوودی در خارج از هند محسوب می شود، جزء ۱۰ فیلم پرفروش سینمای هند قرار دارد. همچنین موفق شده است در رده 85 برترین فیلمهای تاریخ از نگاه سایت معتبر آی.ام.دی.بی قرار گیرد. بازیگرانی چون «عامر خان»، «رانگاناتان مدهوان» و «شارمان جوشی» در این فیلم خوش درخشیده اند. داستان این فیلم درباره دو دوستی است که در جستجوی دوست قدیمیشان هستند. آنها خاطرات تلخ و شیرین زمان دانشگاه و دوستشان را مرور می کنند؛ کسی که باعث شده بود آنها در مورد هر چیزی متفاوت فکر کنند؛ بطوری که دیگران آنها را احمق خطاب می کردند.",
