      "«آمادئوس»، فیلمی در ژانر بیوگرافی-درام و خانوادگی، به کارگردانی «میلوش فورمن» و محصول سال 1984 سینمای آمریکاست. این فیلم حضوری درخشان و افتخارآفرین در جشنواره های داخلی و بین المللی معتبری چون آکادمی اسکار، بفتا و گلدن گلوب داشت و موفق شد نامزد دریافت 58 جایزه شود که در این بین 43 جایزه همچون اسکار «بهترین کارگردانی» و «بهترین بازیگر نقش اول مرد» را از آن خود کرده است. در این فیلم که بر اساس نمایشنامه ای به همین نام اثر «پیتر شِیفِر» ساخته شده، ستارگانی چون «اف. موری آبراهام»، «تام هولس» و «الیزابت بریج» بازی های درخشانی از خود به نمایش گذارده اند. از دیگر افتخارات این فیلم، کسب رتبه 83 در بین 250 فیلم برتر تاریخ سینمای جهان از نگاه سایت معتبر آی.ام.دی.بی است. این فیلم خارق العاده، با موسیقی حیرت انگیز و بازی هایی کم نقص، تصویری سرگرم کننده و تاثیر گذار از زندگی، موفقیت و مشکلات «ولفگانگ آمادئوس موتسارت» را به نمایش می گذارد؛ در حالی که «آنتونیو سالیری»، آهنگساز معاصر، به طرز دیوانه واری به استعداد موتزارت حسادت می کرد و مدعی است که او را به قتل رسانده است...",
