    movie_title: "آپارتمان",
    movie_title_en: "The Apartment",
    HD: true,
    descr:
      "«آپارتمان»، فیلمی در ژانر کمدی-عاشقانه و درام، به کارگردانی «بیلی وایلدر» و محصول سال 1960 سینمای آمریکاست. این فیلم حیرت انگیز و زیبا، پس از اکران عمومی و استقبال فوق العاده مخاطبین و منتقدین، در جشنواره های معتبر داخلی و بین المللی زیادی همچون آکادمی اسکار و گلدن گلوب حضور یافت و موفق به کسب افتخارات فراوانی گشت؛ توانست نامزد دریافت 32 جایزه در بخش های مختلف شود که در این بین، 24 جایزه از جمله «بهترین فیلم»، «بهترین کارگردانی» و «بهترین فیلم نامه غیر اقتباسی» آکادمی اسکار را از آن خود کرده است. در این فیلم که بهترین اثر بیلی وایلدر و شاخص سینمای کمدی سیاه است، ستارگانی چون «جک لمون سی»، «شرلی مک لین» و «فرد مک موری» خوش درخشیده اند. از دیگر افتخارات این فیلم می توان به کسب رتبه 114 بهترین فیلمهای تاریخ از نگاه سایت معتبر آی.ام.دی.بی اشاره نمود. داستان این شاهکار سینمای جهان، درباره کارمند شرکت بیمه است که برای ارتقاء در کارش، آپارتمانش را در اختیار مدیران شرکت قرار می دهد تا در آنجا خوشگذرانی کنند؛ اما همین موضوع باعث به وجود آمدن ماجراهای پیچیده و عاشقانه خودش می شود...",
