    HD: true,
    descr:
      "«قفل، انبار و دو بشکه باروت»، فیلمی در ژانر اکشن-کمدی، به کارگردانی «گای ریچی» و محصول سال 1998 کشور انگلیس است. این فیلم پس از اکران عمومی و جلب نظرات مثبت مخاطبین و منتقدین، با حضور در جشنواره های داخلی و بین المللی معتبری چون بفتا، موفق شد نامزد دریافت 29 جایزه شود که در این بین، 13 جایزه همچون «جایزه ویژه تماشاگران» فستیوال بفتا را از آن خود کرده است. ستارگانی چون «جیسون فلمینگ»، «دکستر فلچر»، «نیک موران» و «جیسون استاتهام» در این فیلم خوش درخشیده اند. از دیگر افتخارات این فیلم، کسب رتبه 152 در بین 250 فیلم برتر تاریخ سینما از نگاه سایت معتبر آی.ام.دی.بی است. این فیلم جذاب با داستانی فوق العاده، از این قرار است که «ادی» می خواهد با حیله های کارت بازی، شرط بندی پوکر را ببرد؛ اما ۵۰۰،۰۰۰ پوند به رئیس یکی از بزرگترین خلافکاران شهر می بازد؛ اکنون تنها یک هفته فرصت دارد تا بدهی خود را پرداخت کند...",
