    movie_title: "در یک شب اتفاق افتاد",
    movie_title_en: "It Happened One Night",
    HD: false,
    descr:
      "«در یک شب اتفاق افتاد»، فیلمی در ژانر کمدی-عاشقانه، به کارگردانی «فرانک کاپرا» می باشد که محصول سال 1934 سینمای آمریکا و از تولیدات کمپانی کلمبیا پیکچرز است. این فیلم که با استقبال کم نظیر مخاطبین و منتقدین مواجه شد، حضوری افتخار آفرین و درخشان در جشنواره های داخلی و بین المللی معتبری چون آکادمی اسکار و ونیز داشت و موفق شد نامزد دریافت 13 جایزه در بخش های مختلفی شود که در این بین، 11 جایزه همچون اسکار «بهترین کارگردانی» و «بهترین بازیگر نقش اول زن و مرد» را از آن خود کرده است. ستارگانی چون «کلارک گیبل»، «کلودت کولبرت» و «والتر کانلی» در این فیلم خوش درخشیده اند. از دیگر افتخارات این فیلم، کسب رتبه 239 در بین 250 فیلم برتر تاریخ سینما، از نگاه سایت معتبر آی.ام.دی.بی است. داستان این شاهکار کمدی جذاب و دوست داشتنی، درباره یک خبرنگار و دختر میلیونر نازپرورده ای است که به طور اتفاقی در اتوبوسی به مقصد نیویورک با هم همسفر می شوند؛ که در نهایت منجر به علاقمند شدن آن ها به هم می گردد.",
