      "رشد کردن می تواند مانند جاده ای پر دست انداز باشد، و رایلی هم از این قضیه مستثنی نیست، کسی که با شروع کار پدرش در سن فرانسیسکو از زندگی غرب میانهٔ خود جدا شده است. مانند همهٔ ما، رایلی هم توسط احساسات خود کنترل می شود، مانند لذت، ترس، خشم، نفرت و غمگین شدن، این احساسات در مرکز ذهن و فرماندهی رایلی به عنوان شخصیت هایی در این انیمیشن زندگی می کنند و صاحب خود را در زندگی روزانهٔ خود راهنمایی می کنند. با تلاش رایلی و احساساتش برای تنظیم خود با یک زندگی جدید، آشفتگی هایی در ذهن او به وجود می آید. گرچه لذت، احساس اصلی و مهمترین احساس رایلی تلاش می کند تا چیزها را مثبت نگه دارد، اما در میان احساسات دیگر برای کنار آمدن با یک شهر، خانه و مدرسهٔ جدید تضاد وجود دارد.",
